import sys
from collections import deque

MOD = 10**9 + 7

def bfs_shortest_paths(graph, start, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def count_paths(graph, start, end, dist, max_dist):
    dp = [[0] * (max_dist + 1) for _ in range(n + 1)]
    dp[start][0] = 1
    for d in range(max_dist + 1):
        for u in range(1, n + 1):
            if dp[u][d] > 0:
                for v in graph[u]:
                    if dist[v] == dist[u] + 1 and d + 1 <= max_dist:
                        dp[v][d + 1] = (dp[v][d + 1] + dp[u][d]) % MOD
    return sum(dp[end]) % MOD

def main():
