    index += 1
    results = []
    while t > 0:
        n, m = map(int, input[index].split())
        index += 1
        s, t = map(int, input[index].split())
        index += 1
 graph = [[] for _ in range(n + 1)]
        for _ in range(m):
            u, v = map(int, input[index].split())
            graph[u].append(v)
            graph[v].append(u)
            index += 1
        dist = bfs_shortest_paths(graph, s, n)
        if dist[t] == -1:
            results.append(0)
        else:
            results.append(count_paths(graph, s, t, dist, dist[t] + 1))
        t -= 1
    for result in results:
